ProjectALife.DialogueShards["replies_ask_22"] = {
{"ASK_PRESIDENT","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"The president? last I heard he was safe, in a bunker, or on a plane, or in some office with a flag behind him","I don't know if he's alive, I don't know if anyone is, I keep waiting for the address","He's supposed to say something, a president always says something, why hasn't he?","My mother voted for him, she's going to be furious, if she's alive","They'd tell us if he were dead -- wouldn't they? they'd have to"}},
{"ASK_PRESIDENT","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Nobody's seen him in weeks, and I don't blame him, I wouldn't show my face either","The president or anyone else, the office doesn't matter, the man doesn't matter, not now","The president can't fix this, nobody can, he'll be the last to say it","Rumor is he's in a bunker in West Virginia, with the cabinet, and a stack of fresh cigars"}},
{"ASK_PRESIDENT","reg=civilian,family,worker,rescue|st=careful",{"Politics? I'm not going there!!","Why, you from the government? You don't look like it"}},
{"ASK_PRESIDENT","role=militia",{"Commander in chief is somewhere far away, giving orders that never get here"}},
{"ASK_PRESIDENT","reg=raider|st=neutral,careful",{"The president? Probably hiding in a bunker with a good cigar and a bad conscience","I didn't vote for him, I didn't vote for anyone, and look how it turned out","He's got a whole army to hide behind, that makes him smarter than most","Who cares, {g:pal|lady}, not like he's coming to save us","Last I heard he was on TV saying stay calm, then the TV went blank, you can guess the rest"}},
{"ASK_PRESIDENT","reg=raider|st=hostile",{"Don't ask me about presidents, I only follow one rule, mine!"}},
{"ASK_PRESIDENT","reg=raider|st=friendly",{"I hope he's alive, honestly, someone has to be in charge somewhere"}},
{"ASK_PRESIDENT","reg=gang|st=neutral,careful",{"The president? He don't know we exist","President ain't never done nothing for my block, why would he start now?","I saw him on TV playing a saxophone, and now we're getting eaten, you tell me what that means","Last I saw he was in a suit saying everything's under control, funny"}},
{"ASK_PRESIDENT","reg=gang|st=hostile",{"President can kiss my ass!"}},
{"ASK_PRESIDENT","reg=gang|st=friendly",{"I hope someone's in charge somewhere, I really do"}},
{"ASK_PRESIDENT","reg=club|st=neutral,careful",{"The president, huh? I voted for the other guy, makes no difference now","President's gone silent, that tells me all I need to know","He'd be the first to run if he could"}},
{"ASK_PRESIDENT","reg=club|st=hostile",{"Don't mention that name around me"}},
{"ASK_PRESIDENT","reg=club|st=friendly",{"Hope he's alright, {g:brother|sister}, even if we didn't see eye to eye"}},
{"ASK_PRESIDENT","reg=crime|st=neutral,careful",{"The president has bigger problems than ours, I imagine","The government has a continuity plan, and it does not include Kentucky","I'd pay good money to know where he is right now"}},
{"ASK_PRESIDENT","reg=crime|st=friendly",{"I hope he and his family are safe, the country needs someone at the helm"}},
{"ASK_PRESIDENT","reg=prison|st=neutral,careful",{"President? Couldn't pick him out of a lineup","Probably got a nice bunker, nice food, nice bed"}},
{"ASK_PRESIDENT","reg=prison|st=hostile",{"Why are you asking me about politics?!"}},
{"ASK_PRESIDENT","reg=prison|st=friendly",{"I wonder if he's thinking of us, doubt it"}},
{"ASK_PRESIDENT","reg=outlaw|st=neutral,careful",{"The president's busy, and so are we","Probably as lost as the rest of us","He's a long way from Knox County, and good for him"}},
{"ASK_PRESIDENT","reg=outlaw|st=friendly",{"If he's alive, I hope he's doing something"}},
{"ASK_PRESIDENT","role=deserter|st=neutral,careful",{"Commander in chief, ha, the commander never told us a thing"}},
{"ASK_PRESIDENT","reg=law|st=neutral,careful",{"The president is alive, as far as we know","We heard a message on the radio that the president would address the nation, then nothing","Wherever he is, I hope he's got a plan"}},
{"ASK_PRESIDENT","reg=law|st=hostile",{"That's not your concern, and it isn't mine either"}},
{"ASK_PRESIDENT","reg=law|st=friendly",{"I have faith in the chain of command, even now"}},
{"ASK_PRESIDENT","role=law_sheriff|st=neutral,careful",{"I've sent him two letters about the county's situation, he hasn't replied"}},
{"ASK_PRESIDENT","reg=military|st=neutral,careful",{"The president is the commander in chief, that is all I can say","Orders come from the top, that's all I know"}},
{"ASK_PRESIDENT","reg=military|st=hostile",{"That information is classified"}},
{"ASK_PRESIDENT","reg=military|st=friendly",{"I hope he's working on a solution, honestly"}},
{"ASK_PRESIDENT","role=soldier_nco|st=neutral,careful",{"The man in charge isn't my concern, the man next to me is"}},
{"ASK_PRESIDENT","role=soldier_green|st=neutral,careful",{"I saw him on TV, I wonder if he's scared like me"}},
{"ASK_PRESIDENT","reg=elite|st=neutral,careful",{"The president is above both our pay grades"}},
{"ASK_PRESIDENT","role=mercenary|st=neutral,careful",{"Whoever's in charge sure as hell hasn't come looking for us"}},
{"ASK_PRESIDENT","role=militia|st=neutral,careful",{"The president hasn't done a thing for rural folks, never will","Prayed for him at church last Sunday, he needs it more than we do"}},
{"ASK_PRESIDENT","role=militia|st=friendly",{"I hope he's doing right by us, I really do"}},
{"ASK_PRESIDENT","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"The president? He's only been in since January, I bet he's never even heard of Muldraugh","The president - is he coming? The TV said he would address the nation - then the TV said nothing","The president? I voted for the other one - guess it doesn't matter now, does it?","I don't care who's president, I care who's at the bridge and whether they'll let us over"},false,{[3]="GENERIC"}},
{"ASK_PRESIDENT","reg=civilian,family|tmp=seasoned|st=friendly,neutral",{"The president? Last time I saw him he was on TV promising things - I don't imagine he's promising anything this week","President's on the far side of the wire with the rest of the country - we're on this side"}},
{"ASK_PRESIDENT","reg=civilian,family,worker,rescue|st=hostile",{"President don't run nothing out here - I do - get"}},
{"ASK_PRESIDENT","reg=worker,rescue|st=friendly,neutral|world=vehicle",{"Whoever it is, they haven't sent one truck of bottled water - you can quote me"}},
{"ASK_PRESIDENT","reg=worker|st=friendly,neutral",{"The president, I think, I vote for the school board, that's about the level of government I can follow"}},
{"ASK_PRESIDENT","reg=law,swat|st=friendly,neutral",{"Commander in chief is the president, chain of command runs through the Governor's office - can't raise either one","Last directive we got came from the state police, not Washington - Washington isn't calling a sheriff in Knox County"}},
{"ASK_PRESIDENT","reg=law,swat|st=careful,hostile",{"Political questions won't get you through here - step back"}},
{"ASK_PRESIDENT","reg=military|tmp=fresh|st=friendly,neutral",{"The President is the commander in chief - uh, we're not supposed to discuss orders - or anything - sorry"}},
{"ASK_PRESIDENT","reg=military,elite|tmp=seasoned,veteran|st=friendly,neutral",{"Commander in chief's in Washington, my orders come from a lot closer than that"}},
{"ASK_PRESIDENT","reg=elite|st=friendly,neutral",{"Chain of command is not your concern"}},
{"ASK_PRESIDENT","reg=military,elite|st=careful,hostile",{"Negative on questions - move away from the barrier"}},
{"ASK_PRESIDENT","reg=outlaw,crime|st=friendly,neutral",{"The president? He'd do alright down here, long as he can run when it counts","Who cares? No president ever did a damn thing for Knox County - why start now?"},false,{[2]="GENERIC"}},
{"ASK_PRESIDENT","reg=raider,gang,club,prison|st=friendly,neutral|world=road",{"President? Hahaha, I'm president of this road, pay the toll"}},
{"ASK_PRESIDENT","reg=raider,gang,club,prison|st=friendly,neutral",{"Washington's done with us, {g:pal|lady}, wrote this county off the day they strung the wire"}},
{"ASK_PRESIDENT","reg=outlaw,raider,gang,club,crime,prison|st=careful",{"Don't care about politics, and I don't care for questions"}},
{"ASK_PRESIDENT","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"The President can't hear you out here - nobody can"}},
{"ASK_PRESIDENT","reg=civilian|tmp=fresh|st=friendly,neutral",{"The president, I guess, I don't know that anybody's told him about us"}},
{"ASK_PRESIDENT","reg=family|st=neutral",{"He was on the TV before it went to the emergency screen - he looked tired"}},
{"ASK_PRESIDENT","reg=worker|tmp=seasoned|st=neutral|mood=funny|world=vehicle",{"I voted for the other fella, right now I'd take either if he brought a truck of food"}},
{"ASK_PRESIDENT","role=rescue_medical|st=neutral",{"I don't care who's president, I care who signs off on a supply convoy"}},
{"ASK_PRESIDENT","role=rescue_clergy|st=friendly,neutral",{"I pray for whoever's in that chair, it's a lonely enough job without this on it"}},
{"ASK_PRESIDENT","role=rescue_firefighter|st=neutral",{"Governor's the one that matters to us, nobody's heard out of Frankfort in a week"}},
{"ASK_PRESIDENT","reg=civilian|tmp=seasoned|st=neutral",{"Somebody's president, somewhere, probably on a plane... right?"},false,{[1]="GENERIC"}},
{"ASK_PRESIDENT","role=family_elder|st=neutral,friendly",{"I've outlived nine of 'em, this ain't the first time I couldn't get a straight word"}},
{"ASK_PRESIDENT","role=law_deputy|st=neutral",{"There was a federal declaration read on the radio on the eighth - then nothing"}},
{"ASK_PRESIDENT","role=law_sheriff|st=neutral|hour=20,5",{"Frankfort quit answering on the ninth - Washington may as well be the moon"}},
{"ASK_PRESIDENT","role=soldier_nco|tmp=veteran|st=neutral",{"I don't discuss the commander in chief, I follow the orders that reach me"}},
{"ASK_PRESIDENT","role=soldier_green|tmp=fresh|st=neutral",{"Is he coming? Somebody said he'd come - that's dumb, right? Why would he come"}},
{"ASK_PRESIDENT","role=elite_delta|tmp=veteran|st=neutral",{"Somebody's giving orders, they reach us late and wrong - that's all I know"}},
{"ASK_PRESIDENT","reg=club|st=neutral",{"Never met a president who knew this county existed - don't expect one to start"}},
{"ASK_PRESIDENT","role=crime_member|st=neutral",{"President's a man who can't reach us, makes him about as useful as the phone"}},
{"ASK_PRESIDENT","role=raider_boss,gang_boss|tmp=predator|st=hostile",{"Ain't no president out here, there's me, and whoever I let stand up"}},
{"ASK_PRESIDENT","reg=civilian|tmp=fresh|st=hostile|world=road",{"Who cares?! There's no government! There's a wire across a road and that's it!"}},
{"ASK_RADIO","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly,neutral",{"We listen every night, it's mostly static, sometimes a voice","My daughter keeps the radio on low, she says it's a friend"}},
{"ASK_RADIO","role=family_elder|tmp=seasoned|st=friendly,neutral",{"The station out of Louisville went silent, the one on 90.3 keeps playing hymns"}},
{"ASK_RADIO","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral",{"I heard a man reading names - hundreds, I stayed up until he stopped","There's an emergency channel, it repeats a message about the cordon"}},
{"ASK_RADIO","role=civilian_loner|tmp=seasoned|st=friendly,neutral",{"Never carried one, prefer silence to bad news"}},
{"ASK_RADIO","role=worker|tmp=seasoned|st=friendly,neutral|world=vehicle,road",{"CB radio in the truck, heard some drivers talking about the highway"}},
{"ASK_RADIO","role=worker|tmp=seasoned|st=friendly,neutral",{"Plant intercom still crackles sometimes - nobody's talking"}},
{"ASK_RADIO","role=rescue_firefighter|tmp=seasoned|st=friendly,neutral",{"Station radio's quiet, dispatch hasn't called since Tuesday"}},
{"ASK_RADIO","role=rescue_medical|tmp=seasoned|st=friendly,neutral",{"Emergency band is mostly distress calls, I stopped listening"}},
{"ASK_RADIO","role=rescue_clergy|tmp=seasoned|st=friendly,neutral",{"I broadcast a service when I can, not many call back"}},
{"ASK_RADIO","role=law_deputy,law_officer|tmp=seasoned|st=friendly,neutral",{"Dispatch is gone, I keep the portable on in case it comes back","We use channel five now, the rest is just noise"}},
{"ASK_RADIO","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly,neutral",{"We run a net out of the sheriff's office, five checkpoints check in every hour"}},
{"ASK_RADIO","role=law_trooper|tmp=veteran|st=friendly,neutral",{"State channel is dead, I've got the CB on, picking up chatter"}},
{"ASK_RADIO","role=law_corrections|tmp=seasoned|st=friendly,neutral",{"Jail radios are down, we use hand signals"}},
{"ASK_RADIO","role=swat_lead,swat_operator|tmp=veteran|st=friendly,neutral",{"Keep the radio quiet unless you really need it"}},
{"ASK_RADIO","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly,neutral",{"Radio silence, those are my orders"}},
{"ASK_RADIO","role=soldier_nco|tmp=veteran|st=friendly,neutral",{"We monitor the net, it's been quiet lately"}},
{"ASK_RADIO","role=deserter,militia|tmp=seasoned|st=friendly,neutral",{"Radios get people found, I smashed mine"}},
{"ASK_RADIO","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=friendly,neutral",{"Radio silence - always"}},
{"ASK_RADIO","role=outlaw|tmp=seasoned|st=friendly,neutral",{"Heard a voice on the CB talking about a safe zone - probably a trick"}},
{"ASK_RADIO","role=raider,raider_boss|tmp=predator|st=friendly,neutral",{"Heard a trade offer on the CB, we're thinking about visiting"}},
{"ASK_RADIO","role=gang_member,gang_boss|tmp=predator|st=friendly,neutral",{"We listen for cops, there aren't any left"}},
{"ASK_RADIO","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral",{"CB's our lifeline - Riders pass news between towns"}},
{"ASK_RADIO","role=crime_member|tmp=seasoned|st=friendly,neutral",{"Radios are for people who don't trust their runners"}},
{"ASK_RADIO","role=prisoner|tmp=predator|st=friendly,neutral",{"Heard a guard shouting on a bullhorn once - then nothing"}},
{"ASK_RADIO","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral",{"Oh God, yes, the radio, there's a voice, a man's voice, he reads names, and I listen for mine, and my family's","Static -- mostly, but if you turn the dial just right, there's a woman who says \"stay inside\"","The emergency broadcast, the one with the beep, it's been looping for days, same message","I have a little transistor, and I check it every hour, and every hour I get nothing","Guy on the CB said there's a safe zone, then he cut off mid-sentence, never heard him again","Heard music last night, a real old song, and I bawled like a baby"}},
{"ASK_RADIO","role=civilian_man,civilian_woman|tmp=seasoned|st=friendly,neutral",{"It's mostly static now, a few signals, a few voices, I don't trust any of 'em","There's a station on the far end of the dial, someone reading the same Bible verse every night","A trucker on the CB, calls himself Night Owl, he tells jokes, and he's the only reason I'm sane","Military frequency, I picked it up by accident, they were talking numbers, coordinates, nothing I could use","Used to listen to the ball game, now I listen for a human voice, any human voice"}},
{"ASK_RADIO","role=civilian_man,civilian_woman|st=friendly",{"Yeah, I've got one, come by later, we'll listen together, it's good to hear a voice, any voice","Of course -- it's the low end of the dial, you tell me anything you pick up, deal?"}},
{"ASK_RADIO","role=civilian_man,civilian_woman|st=careful",{"Radio? what radio? I don't have anything","I'm not telling you what I listen to"}},
{"ASK_RADIO","role=civilian_loner",{"CB, mostly, the truckers are still out there, some of 'em, talking to nobody","Scanner picks up the sheriff's channel, but it's quiet, so quiet it makes my skin crawl","The AM band has one station left, plays hymns around the clock, strange comfort","Don't have one, don't want one, a radio draws attention, and I like my peace"}},
{"ASK_RADIO","role=family_man,family_woman,family_elder,family_youth|st=friendly,neutral",{"We have a battery radio, and we listen for ten minutes every evening, to save the batteries","My son found a channel, kids talking, kids! on the radio, it was the best thing I've heard all week"}},
{"ASK_RADIO","role=family_elder",{"My little kitchen radio, it still plays, but only static, I keep it on for company","I listen to the preacher at noon, he's still there, God bless him, he reads for the shut-ins"}},
{"ASK_RADIO","role=family_youth",{"My brother has a walkie-talkie, and we talk across the field, it's lame, but it works","I found a tape player in a drawer, no batteries, just a tape of my favorite band, I hold it"}},
{"ASK_RADIO","role=worker",{"CB in my truck, no use now, but I leave it on, in case somebody calls","Plant has a PA system, and a handheld, we use it for the watch, it works fine, within a mile"}},
{"ASK_RADIO","role=rescue_medical",{"Ham radio operator at the clinic, he's the only link we have, he tells us what's happening in other counties..","We listen for medical broadcasts... and so far, we've heard nothing"}},
{"ASK_RADIO","role=rescue_clergy",{"The church has an old radio, and we listen for the faithful, they call it the prayer line"}},
{"ASK_RADIO","role=rescue_firefighter",{"Fire frequency, lots of dead air now, sometimes a distant voice, sometimes a scream"}},
{"ASK_RADIO","role=militia",{"We listen to the sheriff's channel, the Guard's frequency, and anything else we can find, mostly static"}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral|mood=fear",{"T-the radio? I heard a woman crying... she was so close, I think she was in the next building","It said \"do not approach,\" over and over -- \"do not approach,\" I turned it off, I was shaking","I keep the volume off... because what if it says something I can't unhear?","Static... static... then a scream... static... I can't listen anymore"}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|mood=grim",{"Nothing useful... mostly static, mostly recordings, mostly lies","A man reading names, every night, same time, same voice, as if names mattered","Radio's mostly garbage... I only believe what I see myself"}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=sad",{"I listen for my son's voice... he was a ham operator... he'd talk to the world... I keep listening","They read my sister's name once... a short list... \"found alive\"... I almost died of joy","I leave it on for company"},false,false,{[3]={{t="the voices help",afterMs=3500},{t="even the static",afterMs=3000}}}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"Nothing but government lies, and music that doesn't fit, and silence, I want to smash it","They broadcast \"remain calm\" to a town on fire, and then they went off the air","Lies, all lies, on every channel"}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=friendly|mood=warm",{"I heard a child singing a lullaby last night, over the air, I don't know who or where, but it was beautiful","Come hear it with me, a voice is a voice, and we could use a few of them","Come listen with me, it's nice not to be alone with it"}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"There's a guy who does a nightly weather report, from inside a bunker, \"partly cloudy, with a chance of the dead\"","Static... and a country song that keeps cutting off at the chorus, it's like the end of the world has a bad DJ, heh","The radio says the weather's perfect for the end of the world, ha","One station plays polka, non-stop","My radio only gets one station... ha"},false,false,{[3]={{t="partly cloudy, chance of the dead",afterMs=3000}},[4]={{t="the end of the world has terrible taste",afterMs=3200}},[5]={{t="a man reading the phone book",afterMs=3200}}}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=careful|mood=fear",{"I don't have a radio, I don't know anything about a radio","The radio is mine, and no, you can't LISTEN"}},
{"ASK_RADIO","role=rescue_medical|st=friendly,neutral",{"We keep a radio at the nurses' station, on low, for the broadcasts, mostly static, sometimes a doctor's voice","A ham operator relays patient numbers... \"four fevers in Brandenburg, six in Rosewood,\" it's all grim..","I listen for hospital frequencies, for anybody saying \"we need help,\" I've answered twice"}},
{"ASK_RADIO","role=rescue_medical|st=careful",{"The radio is for emergencies, not entertainment"}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"The radio can wait... they can't","Turn it off, turn it OFF, they'll hear it","Radio? Not now, shh","If it crackles, they come, keep it off!"}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=player_armed",{"Radio's handy, but your weapon's more useful right now"}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=friendly,neutral",{"Some nights I hear a man reading Bible verses","There's a woman who reads names","Static","I picked up a signal last night, in code","It's a dead hobby now, the radio","Once, I heard a child singing","A man on the CB calls himself \"Night Hawk\"","They broadcast a message on the hour, the same one","I tried every channel","The scanner went quiet","There's music sometimes, an old song","I heard my own voice once... a recording","People call out, \"Is anybody there?\"","Last night a voice said, \"Don't go to the river\"...","It's mostly dead air"},false,false,{[1]={{t="over and over",afterMs=3500},{t="I fall asleep to him",afterMs=3000}},[2]={{t="I hold my breath",afterMs=3500},{t="I'm afraid of every pause",afterMs=3000}},[3]={{t="mostly static",afterMs=3000},{t="sometimes it sounds like breathing",afterMs=3000}},[4]={{t="beep, beep, beep",afterMs=3500},{t="I wish I knew what it meant",afterMs=3000}},[5]={{t="my father taught me, years ago",afterMs=3200},{t="I keep his old set oiled",afterMs=3000}},[6]={{t="just a lullaby, no words",afterMs=3500},{t="I turned the radio off and cried",afterMs=3000}},[7]={{t="tells jokes at two in the morning",afterMs=3200},{t="he's the only reason I'm sane",afterMs=3000}},[8]={{t="\"Remain calm\"",afterMs=3500},{t="I stopped listening",afterMs=3000}},[9]={{t="nothing",afterMs=3200},{t="then I tried them again",afterMs=2800}},[10]={{t="that's how I knew the sheriff's office was gone",afterMs=3500}},[11]={{t="I don't know where it comes from",afterMs=3500},{t="I sing along",afterMs=3000}},[12]={{t="a message I'd left",afterMs=3200},{t="I couldn't stand it",afterMs=3000}},[13]={{t="and nobody answers",afterMs=3500},{t="I always want to",afterMs=3000}},[14]={{t="I won't",afterMs=3500}},[15]={{t="but dead air means someone forgot to turn it off",afterMs=3200},{t="that's something",afterMs=3000}}}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=friendly|hour=16,5",{"Come hear it with me tonight!"},false,false,{[1]={{t="it's better with company",afterMs=3200}}}},
{"ASK_RADIO","reg=civilian,family,worker,rescue|st=careful",{"I don't discuss what I listen to","What radio?","I don't have one","Why? you want to listen in?","That's off limits!","What do you want with a radio? Who are you calling? Stay back there","I don't tell folks what frequency we're on, you can understand why"}},
{"ASK_RADIO","role=civilian_loner|st=friendly,neutral",{"Never carried one","Heard one once, in a farmhouse"},false,false,{[1]={{t="a radio's a way for the world to find you",afterMs=3500}},[2]={{t="a man praying",afterMs=3200},{t="I left the room",afterMs=2800}}}},
