{"ASK_RADIO","role=worker|st=friendly,neutral",{"CB at the shop","Plant PA's still working"},false,false,{[1]={{t="truckers, mostly",afterMs=3500},{t="they keep me company",afterMs=3000}},[2]={{t="I use it to call the shift",afterMs=3200}}}},
