{"ASK_REMEDY","reg=raider|st=neutral,careful",{"For a cough? Whiskey and honey, if you can find them"}},
{"ASK_REMEDY","reg=gang|st=neutral,careful",{"My grandma swore by onions in your socks"}},
{"ASK_REMEDY","reg=club|st=neutral,careful",{"Whiskey and honey in hot water, tastes awful, works great"}},
{"ASK_REMEDY","reg=crime|st=neutral,careful",{"Rest, fluids, and a glass of brandy"}},
{"ASK_REMEDY","reg=prison|st=neutral,careful",{"Honey, if you find it, or hot salt water"}},
{"ASK_REMEDY","reg=outlaw|st=neutral,careful|world=trees",{"Pine needle tea, steeped hot, tastes like a Christmas tree"}},
{"ASK_REMEDY","reg=law|st=neutral,careful",{"Fluids, rest, and cough syrup, if you can find it"}},
{"ASK_REMEDY","reg=military|st=neutral,careful",{"The medic recommends lozenges and rest"}},
{"ASK_REMEDY","role=militia|st=neutral,careful",{"Honey, vinegar, and hot tea, my wife's recipe"}},
